logger = Logger("LC")


class CliInterface:
    """Interface for logcollector cli application."""

    def __init__(self):
        """Basic initialization."""
        self._taf_tl_config: TestLine = None
        self._config = {}
        self.hosts = {}
        global logger
        logger = get_net_logger(SERVER_HOST, LOGGER_PORT, name=f"{self.__class__.__name__}")
        CliInterface._check_new_ver()
        run_tcp_server()

    def start_collecting_logs(self, configuration: dict) -> None:
        """
        Configure and start logging.

        :param configuration: python dict with configuration
        """
        self._setup(configuration)
        # if self.config.get("emil", {}).get("active", False):
        #     backup_btslog_configuration(logger=logger, hosts=self.hosts)
        plugins = plugin_request.Builder("cli", self.config).build()
        log_dir_path, tmp_dir = create_dir_for_logs(logger, self.config["main"]["store"])
        with open("/tmp/logcollector/loc.log", "w+") as f:
            f.write(f"{log_dir_path} {tmp_dir}")
        start_runners(logger=logger, hosts=self.hosts, log_dir=tmp_dir, plugins=plugins)

    def stop_collecting_logs(self, configuration: dict) -> None:
        """Stop logging and collect logs."""
        self._setup(configuration)
        stop_runners(logger, self.hosts)
        with open("/tmp/logcollector/loc.log") as f:
            log_dir_path, tmp_dir = f.read().split()
        get_logs_from_runners(
            logger=logger,
            hosts=self.hosts,
            compression_type=self.config["main"]["compress"],
            remote_logs_path=tmp_dir,
            local_path=log_dir_path,
        )
        # if self.config.get("emil", {}).get("active", False):
        #     restore_btslog_configuration(logger=logger, hosts=self.hosts)

    @property
    def config(self) -> dict:
        """
        Returns configuration as dict.

        :return: configuration
        """
        return self._config

    @config.setter
    def config(self, configuration: dict) -> None:
        """
        Write configuration from python dict.

        :param configuration: configuration as python dict
        """
        self._config.update(configuration)

    @property
    def taf_tl_config(self):
        if not self._taf_tl_config:
            self._taf_tl_config, _ = get_tl_cfg(logger)
        return self._taf_tl_config

    def _setup(self, configuration: dict) -> None:
        """
        Performs setup for logcollector, starts lc_server, builds plugins and prepares directories for further use
        :param configuration: Path to yaml file or python dict
        """
        # todo: duplication with RobotInterfece
        self.config = migrate(logger, configuration)
        update_config_for_plugins(self.config, self.taf_tl_config, logger)
        self._detect()
        ServerStartupManager(self.hosts).start()

    def _detect(self):
        """Detect VM configuration and make update if necessary."""
        # todo: duplication with RobotInterfece
        hosts = self.taf_tl_config.test_pcs
        result = bool(len(hosts))
        list_of_configured_vms = [key for key in self._config["main"].keys() if key.startswith("vm")]
        if result and list_of_configured_vms:
            for host_id, addr in self._union_of_configurations().items():
                list_of_configured_vms.remove(host_id)
                addr = SERVER_HOST if addr in ("127.0.0.1", "localhost") else addr
                self._config["main"][host_id]["addr"] = addr
            for host_id in list_of_configured_vms:
                del self._config["main"][host_id]
        elif result:
            for host_id, host in enumerate(hosts, start=1):
                ssh_info = host.default_ssh_connection_details
                addr = SERVER_HOST if ssh_info.addr == "127.0.0.1" else ssh_info.addr
                addr = SERVER_HOST if addr in ("127.0.0.1", "localhost") else addr
                self._config["main"][f"vm{host_id}"] = {
                    "addr": addr,
                    "usr": ssh_info.username,
                    "passwd": ssh_info.password,
                }
        else:
            for vm_id in list_of_configured_vms:
                del self._config["main"][vm_id]
            self._config["main"]["vm1"] = {"addr": SERVER_HOST, "usr": "ute", "passwd": "ute"}
            logger.warning("Configuration not detected. Trying to start on default (local) host.")

        self.hosts = {
            host_id: vm_host(
                self._config["main"][host_id]["addr"],
                self._config["main"][host_id]["usr"],
                self._config["main"][host_id]["passwd"],
                False,
            )
            for host_id in [vm_key for vm_key in self._config["main"].keys() if vm_key.startswith("vm")]
        }

    def _union_of_configurations(self) -> dict:
        """
        Make comparison with config from testline_configuration repository and configuration provided by user.
        Return union of configurations.

        :return: dict with VM's IP addresses
        """
        res = {}
        for index, host in enumerate(self.taf_tl_config.test_pcs, 1):
            ssh_info = host.default_ssh_connection_details
            addr = SERVER_HOST if ssh_info.addr == "127.0.0.1" else ssh_info.addr
            try:
                vm_addr = self._config["main"][f"vm{index}"]["addr"]
                if vm_addr in (addr, "", SERVER_HOST):
                    res[f"vm{index}"] = addr
            except KeyError:
                pass
        return res

    @staticmethod
    def _check_new_ver():
        new_ver, latest = new_version_exists("ta_logcollector", __version__)
        if new_ver:
            logger.warning(f"New ta_logcollector version available: {__version__} -> {latest}")


def parse_config(cli_args: Namespace) -> dict:
    """
    Parse cli arguments to python dict.
    It handles applying default configuration logic:
    1. if --yamlfile opts is present - try load yaml and return python dict
    2. In only start is provided default.yml is used

    :param cli_args: cli argument list
    :return: dict with configuration
    """
    if not cli_args.yamlfile:
        return read_config(yaml_file=path.join(path.dirname(getfile(parse_config)), "default.yml"))
    elif cli_args.action == "start" and cli_args.yamlfile:
        return at_least_one_plugin_is_active(read_config(yaml_file=cli_args.yamlfile))
    elif cli_args.action == "stop" and cli_args.yamlfile:
        return read_config(yaml_file=cli_args.yamlfile)


def at_least_one_plugin_is_active(configuration: dict) -> dict:
    """
    Raise ValueError if none of plugins are active, return original configuration otherwise.

    :param configuration: LC configuration dict
    :raises ValueError: if none of plugins are active
    """
    if any(configuration[plugin].get("active", False) for plugin in configuration):
        return configuration
    raise ValueError("None of plugins are active", configuration)


def kill_tcp_server():
    """Kill TCP server process by checking its PID."""
    pid = get_python_process_pid_by_command("lc_logserver", "python.*lc_logserver.*")
    kill_process_by_pid(pid)


def kill_lc_servers(hosts: dict) -> None:
    """Kill remotely all lc_servers"""
    for host_id, host_data in hosts.items():
        pid = get_python_process_pid_by_command("lc_server", "python.*lc_server.*", host_data=host_data)
        kill_process_by_pid(pid, host_data=host_data)


def kill_tcp_log_server(logger: Logger) -> None:
    logger.debug(LC_LOG_SERVER_ABORT)


def run_tcp_server():
    """Run TCP logging server"""
    if not is_proper_tcp_server_running():
        kill_tcp_server()
        try:
            output_dir = BuiltIn().get_variable_value("${OUTPUT_DIR}")
        except RobotNotRunningError:
            output_dir = gettempdir()
        cmd = "nohup {py_env}/bin/lc_logserver{py_ver} -d {path} -v {lc_ver} -l {log_lvl} >>$HOME/lc.log 2>&1 &"
        server_cmd = cmd.format(
            py_env=exec_prefix,
            py_ver=version_info[0],
            path=output_dir,
            lc_ver=__version__,
            log_lvl=environ.get("LC_CONSOLE_LOG_LVL", "WARNING"),
        )
        call([server_cmd], universal_newlines=True, shell=True)
        sleep(2)  # receiver_tcp_server takes a moment till it's ready to receive logs. Sleep prevents losing some logs


def get_running_server_data(process_command: str, regexp: str) -> str:
    """
    Gets data of launched receiver tcp server based on regexp from output of ps command
    :param process_command: single line of output from ps command
    :param regexp: regular expresion
    :return: receiver tcp server version or Unknown
    """
    try:
        return search(rf"{regexp}", process_command).group(1)
    except AttributeError:
        return "Unknown"


def is_proper_tcp_server_running() -> bool:
    """
    Check if TCP server is running.

    :return: True or False whether server is running or not
    """
    log_lvl_regexp = r"-l (CRITICAL|ERROR|WARNING|INFO|DEBUG)(\s|$)"
    ver_regexp = r"-v ([0-9.]*)(\s|$)"
    for proc in get_python_process_info_from_ps_output("lc_logserver", "python.*lc_logserver.*"):
        cmd = proc.group("CMD")
        conditions = [
            cmd.startswith(("python", executable, exec_prefix)),
            exec_prefix in cmd,
            get_running_server_data(cmd, ver_regexp) == __version__,
            get_running_server_data(cmd, log_lvl_regexp) == environ.get("LC_CONSOLE_LOG_LVL", "WARNING"),
        ]
        if all(conditions):
            return True
    return False
